from collections import defaultdict
edits = defaultdict(list)
for f, old, new in R: edits[f].append((old, new))
ok = 0; fail = 0
for f, lst in edits.items():
    s = open(f, encoding="utf-8").read()
    for old, new in lst:
        c = s.count(old)
        if c == 1: s = s.replace(old, new); ok += 1
        else: fail += 1; print("  !! match=%d in %s :: %s" % (c, f, old[:50]))
    open(f, "w", encoding="utf-8").write(s)
print("applied OK:", ok, "| failed:", fail)
